import csv, os
# 今日有效签署单（签署日2，名册按签署日2）：start<=3<=end，正式，签发人获授权
valid = {  # 对象: (流水, 主站)
 'HZ-A':('2001','南站'), 'HZ-B':('2005','南站'), 'JL-A':('2011','东港'), 'JL-B':('2016','西湾'),
 'NP-A':('2020','西湾'), 'NP-B':('2026','北仓'), 'YC-A':('2031','东港'), 'YC-B':('2035','东港'),
 'QH-A':('2041','南站'), 'QH-B':('2046','北仓'), 'BA-A':('2050','北仓'), 'BA-B':('2056','西湾')}
cat = {'P01':'驻场','P02':'驻场','P03':'驻场','P04':'送修','P05':'送修','P06':'送修','P07':'驻场',
       'P08':'送修','P09':'驻场','P10':'驻场','P11':'驻场','P12':'送修'}
obj = {'P01':'HZ-A','P02':'HZ-B','P03':'JL-A','P04':'JL-B','P05':'NP-A','P06':'NP-B',
       'P07':'YC-A','P08':'YC-B','P09':'QH-A','P10':'QH-B','P11':'BA-A','P12':'BA-B'}
# 设备申请：同设备序号取最大修订号；取消不占
app = {}
with open('../inbox/06-03/设备申请.csv', encoding='utf-8-sig') as f:
    for r in csv.DictReader(f):
        c=r['案号']; dev=r['设备序号']; rev=int(r['修订号'])
        key=(c,dev)
        cur=app.get(key)
        if cur is None or rev>cur[0]:
            app[key]=(rev,int(r['申请席位']),r['状态'],int(r['优先号']))
need={}; prio={}
for (c,dev),(rev,seats,st,pr) in app.items():
    prio[c]=pr
    if st.strip()=='取消': continue
    need[c]=need.get(c,0)+seats
print('需求',dict(sorted(need.items())),'优先',prio)
cert = {('东港','驻场'):'S11',('东港','送修'):'S12',('西湾','驻场'):'S21',('西湾','送修'):'S22',
        ('南站','驻场'):'S31',('南站','送修'):'S32',('北仓','驻场'):'S41',('北仓','送修'):'S42'}
cap={'东港':8,'西湾':9,'南站':7,'北仓':8}
release=['P01','P02','P03','P04','P05','P06','P07','P09','P10','P11']
order=sorted(release,key=lambda c:(prio[c],c))
alloc={}; rows=[]
for c in order:
    o=obj[c]; S=valid[o][1]; n=need[c]
    if cap[S]>=n:
        alloc[c]=n; cap[S]-=n
    else:
        alloc[c]=0
    rows.append((c,o,cat[c],S,cert[(S,cat[c])],n,alloc[c],cap[S],prio[c]))
for r in rows: print(r)
print('剩余',cap)
import json
json.dump({'alloc':alloc,'rows':rows,'cap':cap},open('../scratch/alloc0603.json','w'),ensure_ascii=False)
PY

